(function(){
  "use strict";
  const stories = [
    {
      id:"the-second-pair-of-shoes",
      title:"The Second Pair of Shoes",
      category:"Family, Dignity & Sacrifice",
      tagline:"She wanted the world to see her new shoes. She never noticed the hands that made them.",
      summary:"A schoolgirl becomes embarrassed by her father's humble work as a roadside cobbler. On the day she is honoured, she discovers the quiet sacrifice behind every step she has taken.",
      dateLabel:"30 October 2026",
      paragraphs:[
        "The first time Ada noticed the smell of leather on her father's hands, she was eight years old. She had run home from school, thrown her arms around him and asked why his fingers always smelled like old shoes.",
        "Her father, Mr. Okoro, laughed. “Because these hands are trying to take you somewhere better.”",
        "He repaired shoes beneath a faded blue umbrella beside the busy road in Enugu. His wooden stool was uneven, his toolbox was older than Ada, and the sign above his little space simply read: OKORO — SHOE REPAIRS.",
        "Every morning, he left home before Ada woke up. Every evening, he returned with dust on his trousers and tiny cuts on his fingers. But he never came home without asking the same question: “What did you learn today?”",
        "Ada was a bright student. Her teachers praised her essays, her mathematics and the way she spoke during debates. Her father kept every report card in a biscuit tin beneath his bed.",
        "As Ada grew older, however, she began to notice the difference between her father's life and the lives of other parents. Some arrived at school in cars. Some wore suits and polished watches. Her father arrived in a shirt that had been washed so many times its colour had almost disappeared.",
        "One visiting day, he came to school carrying her lunch in a small plastic bowl. Ada saw two classmates looking at his dusty sandals and laughing.",
        "“Is that your father?” one whispered.",
        "Ada nodded, but she did not run to him as she usually did. She collected the bowl quickly and asked him to leave before the bell rang.",
        "Her father noticed the change. He said nothing. He only asked, “Did you eat?”",
        "“Yes, Daddy,” she replied, although shame had taken away her appetite.",
        "A few weeks later, Ada was selected to represent her school at a regional academic competition. The winner would receive a scholarship that could support her university education.",
        "She was excited. For the first time, she imagined a future in which her father would no longer have to sit by the roadside repairing other people's shoes.",
        "“Daddy, I want to win,” she told him.",
        "He placed both hands on her shoulders. “Then prepare well. Let your work speak for you.”",
        "The competition was scheduled for a Saturday. Ada needed a pair of black shoes for the ceremony. Her old pair had split near the sole, and the school had made it clear that contestants must dress formally.",
        "Her father examined the shoes under the light of a small bulb.",
        "“I can repair these,” he said.",
        "“Daddy, I don't want repaired shoes. I want new ones. Everybody will be looking at us.”",
        "He looked at her for a moment, then nodded. “All right. Let me see what I can do.”",
        "That night, Ada woke to the sound of a needle passing through leather. Her father was sitting near the doorway, working beneath a weak rechargeable lamp. On the floor beside him lay a pair of black shoes he had been making from leftover leather.",
        "She watched for a moment, then returned to bed.",
        "The next morning, he placed the shoes beside her school bag. They were simple, carefully stitched and polished until they shone.",
        "“I made them for you,” he said.",
        "Ada tried them on. They fitted perfectly. But she frowned. “Daddy, they still look handmade.”",
        "Her father's smile became smaller. “Yes. They are.”",
        "She carried them to school without saying thank you.",
        "On the morning of the competition, Ada stood before the mirror in her uniform and black shoes. Her father adjusted her collar, brushed a little dust from her shoulder and reached for his old jacket.",
        "“Are you coming?” she asked.",
        "“I will come,” he promised. “I have one delivery to make first.”",
        "At the venue, Ada searched the audience before the competition began. Parents sat together, taking photographs. She saw polished shoes, bright clothes and expensive phones. She did not see her father.",
        "The questions were difficult. Ada's hands trembled at first, but she remembered his words: Let your work speak for you. She breathed deeply and answered one question after another.",
        "When the results were announced, her name came first.",
        "The hall erupted in applause. Ada walked to the stage and received her certificate. A photographer asked her to stand with her parents, but the chair beside her was empty.",
        "She smiled for the camera anyway.",
        "After the ceremony, her teacher approached her. “Ada, your father came earlier. He was standing outside the hall.”",
        "“Where is he now?”",
        "“He said he had to return to work. He asked me to tell you he was proud.”",
        "Ada felt a sudden sting in her chest. She walked outside and found no sign of him.",
        "When she reached home, she found her father asleep in his chair. His right hand was wrapped in a piece of cloth. Beside him lay a small brown envelope.",
        "Inside the envelope was a receipt for the scholarship registration and examination expenses. There was also a note in his handwriting: “For Ada. One step at a time.”",
        "Under the note was a folded photograph. It showed her father at the roadside, holding the finished shoes in one hand. His other hand was bleeding where the needle had pierced his finger.",
        "Ada looked at the shoes she was wearing. For the first time, she did not see a rough pair of handmade shoes. She saw the hours he had spent working after dark. She saw the money he had saved. She saw the hands that had carried her books, washed her uniform when she was ill and held her bicycle when she was learning to ride.",
        "She knelt beside his chair.",
        "“Daddy,” she whispered.",
        "He woke slowly. “How did it go?”",
        "“I won.”",
        "His face brightened. “I knew you could do it.”",
        "Ada held his injured hand carefully. “I'm sorry I was ashamed of you.”",
        "He looked confused for a moment. Then he gently touched her cheek.",
        "“My daughter, there is nothing shameful about honest work. These hands may not wear expensive rings, but they have never stolen your future from anybody.”",
        "Ada began to cry. “I wanted you to be like the other fathers.”",
        "He smiled tiredly. “And I only wanted you to have choices I never had.”",
        "Years later, Ada would remember that day more clearly than the applause, the certificate or the scholarship. She would remember the small brown envelope, the injured hand and the man who had made her shoes while the rest of the world slept.",
        "When she graduated from university, she did not ask her father to sit at the back of the hall. She reserved the front seat for him. She polished his old shoes herself and placed them beside the chair.",
        "Before the ceremony began, she bent down and whispered, “Today, Daddy, everybody will see the man who brought me here.”",
        "He held her hand. The same hands that had once repaired broken shoes trembled as he wiped his eyes.",
        "Some people build our future in places nobody applauds. They work beneath umbrellas, behind counters, beside roads and in rooms lit by weak bulbs. Their clothes may be simple, but their sacrifices are not.",
        "Never measure a person's worth by the shine of their shoes. Sometimes, the hands that make the smallest living are the hands carrying the biggest dreams.",
        "And if someone has been working quietly to help you take the next step, do not wait until you reach the top before you turn around and say thank you."
      ]
    },
    {
      id:"last-plate", title:"The Last Plate", category:"Family & Sacrifice",
      tagline:"She always said she had eaten.",
      summary:"A widowed mother gives her son everything she can, quietly hiding her own hardship until he finally understands the cost of her love.",
      dateLabel:"Opening story",
      paragraphs:[
        "Every evening, before Daniel went to bed, he asked his mother the same question.",
        "“Mama, have you eaten?”",
        "And every evening, she gave him the same answer.",
        "“Yes, my son. I have eaten. Eat your own before it gets cold.”",
        "Daniel never questioned her answer. Why would he? She was his mother. And mothers, he believed, always knew how to take care of themselves.",
        "But there was something Daniel did not know. Sometimes, his mother had not eaten since the previous morning.",
        "Mama Grace was a poor widow who sold tomatoes and peppers in a small Nigerian market. Her daily earnings were barely enough to keep food on the table and send her only son to school.",
        "Yet, whenever food was ready, Daniel received the biggest portion. If there was meat, he got it. If there was an egg, it was his. If there was only enough rice for one full plate, Mama Grace made sure it was Daniel who ate well.",
        "When he complained that she had too little, she would smile and say, “I ate while cooking.” He believed her.",
        "One morning, Daniel needed money to complete his school fees. His mother counted the money she had saved, again and again, hoping the figures would somehow change. They did not.",
        "That afternoon, Mama Grace removed the earrings her late husband had given her. She wrapped them in a small piece of cloth and sold them. When Daniel returned home, his school fees were ready.",
        "“Mama, where did you get the money?” he asked.",
        "She smiled. “A mother has many places to find money.”",
        "Daniel promised that one day he would repay every sacrifice she had made. Mama Grace touched his face and said, “Don't worry about repaying me. Just become a good person.”",
        "Years passed. Daniel grew up, finished school and travelled to Lagos in search of a better life. At the bus park, his mother placed her last savings in his hand.",
        "“Mama, what will you use?” he asked.",
        "“I have enough,” she replied.",
        "He hugged her and promised to call every day.",
        "At first, he did. But life in the city was not easy. Daniel worked long hours, struggled with bills and chased opportunities. Some days, he was too tired to talk. Other days, he told himself he would call his mother tomorrow.",
        "And tomorrow became next week. Next week became next month.",
        "Whenever they spoke, Mama Grace asked whether he was eating well.",
        "“I'm fine, Mama,” he would say. “Don't worry about me.”",
        "She would laugh softly. “As long as you are fine, I am fine.”",
        "Neither of them told the other the whole truth. Daniel did not tell her how lonely and exhausted he sometimes felt. Mama Grace did not tell him how difficult life had become.",
        "She continued selling vegetables, even on days when her body begged her to rest. She patched her old clothes, reduced her meals and saved whatever little she could. She wanted her son to succeed without carrying the weight of her suffering.",
        "Then, one evening, Daniel called with wonderful news.",
        "“Mama! I got the job! A better job, with better pay!”",
        "Mama Grace sat down, tears gathering in her eyes. “God has answered my prayers,” she whispered.",
        "Daniel laughed. “Mama, very soon, I'll buy you a big house. I'll get you a new bed, a refrigerator and everything you need. I'm coming home next month.”",
        "For a long time, Mama Grace said nothing.",
        "“What's wrong, Mama?” Daniel asked.",
        "“Nothing, my son. I'm just happy.”",
        "Then she made one request.",
        "“When you come, don't buy anything expensive. Just come and eat with me.”",
        "Daniel laughed. “Make plenty of rice, Mama. Your son is coming home hungry!”",
        "They laughed together. It was the last happy conversation they would ever have.",
        "The following weeks passed slowly for Mama Grace. She began preparing for her son's visit. She cleaned the little house, washed his old bedsheet and bought the ingredients for his favourite meal: rice, stew and a small piece of chicken.",
        "She placed two plates on the table. One for Daniel. One for herself.",
        "A neighbour, Aunty Bisi, found her cooking that evening.",
        "“Grace, you should rest,” she said. “You've been working too hard.”",
        "Mama Grace smiled as she stirred the pot. “My son is coming tomorrow.”",
        "“You can cook when he arrives.”",
        "“No,” Mama Grace replied gently. “I want everything ready. He has suffered enough out there. Let me take care of him when he comes home.”",
        "Aunty Bisi looked at her and shook her head. “You mothers will never stop being mothers.”",
        "Mama Grace laughed. But a few minutes later, while reaching for the pot, she suddenly became weak. The spoon slipped from her hand. She tried to hold the table, but her knees gave way.",
        "Aunty Bisi rushed towards her. “Grace! Grace, can you hear me?”",
        "Mama Grace struggled to speak. “Please… don't let the food burn.”",
        "Those were the last words she ever spoke.",
        "The next morning, Daniel bought a beautiful wrapper and a pair of sandals for his mother. He was finally going home, ready to fulfil some of the promises he had made.",
        "Then his phone rang. It was Aunty Bisi.",
        "“Daniel,” she said, her voice trembling. “My son, please be strong.”",
        "He stopped walking. “What happened? Is my mother all right?”",
        "Aunty Bisi began to cry.",
        "Daniel's gift bag slipped from his hand. “No,” he whispered. “No, please. Let me speak to her.”",
        "But there was no one left to answer his call.",
        "When Daniel arrived home, his mother's chair was empty. The house that had once welcomed him with laughter and the smell of freshly cooked food was silent. His mother had been buried. He had arrived too late.",
        "Days later, Aunty Bisi handed him a small old tin she had kept for Mama Grace.",
        "Inside were school-fee receipts, a faded photograph of Daniel as a little boy, and several pieces of paper covered in his mother's handwriting.",
        "He opened the first note: “Daniel's school fees paid. I will manage until the next market day.”",
        "He opened another: “Daniel needs new shoes. I can manage with the old ones.”",
        "Another note read: “He sounded tired on the phone today. I wanted to tell him things are difficult here, but I don't want him to worry. Let him concentrate on his future.”",
        "Daniel's hands began to shake. All those years, he had believed his mother was fine. Now, he understood what her words had really meant. She had been protecting him from the very suffering she was enduring.",
        "He pressed the notes against his chest and began to cry. “Why didn't she tell me?” he asked.",
        "Aunty Bisi sat beside him. “She didn't want to become a burden to you, Daniel. She wanted you to succeed. Every time you told her you were doing well, she went to bed happy.”",
        "Daniel looked towards his mother's room. “I thought I still had time,” he whispered.",
        "Nobody answered.",
        "That evening, he sat alone at the wooden table where his mother had fed him for most of his life.",
        "He placed a plate before himself. Then, without thinking, he reached for a second plate.",
        "His hand stopped halfway.",
        "He stared at the empty chair opposite him.",
        "For the first time, he remembered every evening she had said, “I have eaten.” He remembered the earrings she had sold, the money she had placed in his hand, the calls he had ended because he was busy, the promises he had postponed until he became successful, and the one request she had made before she died.",
        "Just come and eat with me.",
        "Daniel bowed his head. “Mama,” he whispered into the silence, “have you eaten?”",
        "There was no answer. Only the quiet room, the empty chair and the plate his mother would never use again.",
        "Daniel had finally become the man she had prayed he would become. But he had learned the value of her sacrifices at a time when he could no longer thank her.",
        "Some people spend their lives giving us what they never had. They hide their hunger so we can eat. They hide their tears so we can smile. They postpone their happiness so we can have a better future.",
        "And sometimes, we become so busy building that future that we forget the people who sacrificed everything to give it to us.",
        "We tell ourselves there will be time to visit. Time to call. Time to sit together and talk. Time to say thank you.",
        "But tomorrow is not a promise.",
        "If your mother is still alive, don't wait until you can afford to give her the whole world before you give her your time. Call her. Visit her. Sit beside her. Share a meal with her.",
        "And before you ask her what she needs, ask her the question Daniel asked his mother every evening: “Have you eaten?”",
        "Because one day, the chair opposite you may be empty. And the meal you kept promising to share may become the meal you can never share again."
      ]
    }
    ,

  ];
  function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;}
  function init(){
    if(document.getElementById("story-story-pavilion"))return;
    const campus=document.getElementById("campus");
    if(!campus)return;
    const pavilion=el("button","");
    pavilion.id="story-story-pavilion";pavilion.type="button";
    pavilion.setAttribute("aria-label","Open STORY STORY daily stories");
    pavilion.innerHTML='<span class="story-story-count">${stories.length} STORIES</span><div class="story-story-roof"></div><div class="story-story-sign"><strong>STORY STORY!!</strong><span>Stories that touch the heart</span></div><div class="story-story-columns"><i></i><i></i><i></i><i></i></div><div class="story-story-door"></div><div class="story-story-steps"></div>';
    campus.appendChild(pavilion);
    const overlay=el("div","story-story-overlay");overlay.id="storyStoryOverlay";overlay.setAttribute("aria-hidden","true");
    const card=el("section","story-story-card");card.setAttribute("role","dialog");card.setAttribute("aria-modal","true");card.setAttribute("aria-labelledby","storyStoryTitle");
    const head=el("header","story-story-head");head.innerHTML='<div class="story-story-kicker">VOICES OF HUMANITY · DAILY STORY GALLERY</div><h2 id="storyStoryTitle">STORY STORY!!</h2><p>Every story carries a feeling. Every life holds a story. Come in, take a moment, and read.</p>';
    const close=el("button","story-story-close","×");close.type="button";close.setAttribute("aria-label","Close Story Story");head.appendChild(close);
    const body=el("div","story-story-body"),list=el("div","story-story-list"),reading=el("article","story-story-reading"),footer=el("div","story-story-footer","New original stories will be added here regularly. Stories and images are presented within the Voices of Humanity Museum.");
    body.append(list,reading,footer);card.append(head,body);overlay.appendChild(card);document.body.appendChild(overlay);
    let selected=0;
    function renderStory(index){
      selected=index;list.replaceChildren();stories.forEach((story,i)=>{const b=el("button","story-story-item");b.type="button";b.setAttribute("aria-pressed",String(i===index));b.append(el("span","",story.category),el("strong","",story.title),el("p","",story.summary));b.addEventListener("click",()=>renderStory(i));list.appendChild(b);});
      const story=stories[index];reading.replaceChildren();reading.append(el("h3","",story.title),el("p","story-story-tagline",story.tagline));
      story.paragraphs.forEach(p=>reading.appendChild(el("p","",p)));
    }
    function open(){
      selected=0;
      renderStory(selected);overlay.classList.add("open");overlay.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";close.focus();}
    function shut(){overlay.classList.remove("open");overlay.setAttribute("aria-hidden","true");document.body.style.overflow="";pavilion.focus();}
    pavilion.addEventListener("click",open);close.addEventListener("click",shut);
    overlay.addEventListener("click",e=>{if(e.target===overlay)shut();});
    document.addEventListener("keydown",e=>{if(e.key==="Escape"&&overlay.classList.contains("open"))shut();});
    // Do not auto-open an older archived story from a stale URL hash.
  }
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
  window.addEventListener("load",init,{once:true});
})();